use std::io::{Read, Write};
use std::net::{Ipv4Addr, Shutdown, TcpListener, TcpStream};
use std::thread;
use std::time::Duration;

use super::support::proxy::{ephemeral_proxy_config, start_proxy};
use super::support::socks5::socks_connect;

const BODY: &[u8] = b"GET / HTTP/1.1\r\nHost: example.com\r\nUser-Agent: abcdef\r\n\r\n";
// Generated by hyper-h2 4.3.0: preface, SETTINGS, HPACK POST headers and the DATA frame header.
const H2_FIRST: &[u8] = b"PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n\x00\x00*\x04\x00\x00\x00\x00\x00\x00\x01\x00\x00\x10\x00\x00\x02\x00\x00\x00\x01\x00\x04\x00\x00\xff\xff\x00\x05\x00\x00@\x00\x00\x08\x00\x00\x00\x00\x00\x03\x00\x00\x00d\x00\x06\x00\x01\x00\x00\x00\x00\x17\x01\x04\x00\x00\x00\x01\x83\x86A\x88/\x91\xd3]\x05\\\x87\xa7D\x85b\xda\xe88\xe4\\\x82m\xdf\x00\x009\x00\x01\x00\x00\x00\x01";

#[test]
fn http_mod_preserves_separately_sent_request_body() {
    let _guard = super::test_guard();
    let first = b"POST /upload HTTP/1.1\r\nHost: outer.example\r\nContent-Length: 57\r\n\r\n";
    let expected = b"POST /upload HTTP/1.1\r\nHost: OuTeR.ExAmPlE\r\nContent-Length: 57\r\nX-Pad: 01234567890123456789012345678901\r\n\r\n";
    assert_eq!(BODY.len(), 57);
    assert_eq!(send_in_two_reads(first, expected, true), BODY);
}

#[test]
fn http_mod_preserves_http2_data_after_the_frame_header() {
    let _guard = super::test_guard();
    assert_eq!(H2_FIRST.len(), 116);
    assert_eq!(send_in_two_reads(H2_FIRST, H2_FIRST, false), BODY);
}

fn send_in_two_reads(first: &[u8], expected_first: &[u8], http: bool) -> Vec<u8> {
    let listener = TcpListener::bind((Ipv4Addr::LOCALHOST, 0)).expect("bind owned origin");
    let port = listener.local_addr().expect("origin port").port();
    let expected_first = expected_first.to_vec();
    let origin = thread::spawn(move || {
        let (mut peer, _) = listener.accept().expect("accept origin");
        peer.set_read_timeout(Some(Duration::from_secs(3))).expect("bound origin read");
        let mut received = Vec::new();
        if http {
            while !received.ends_with(b"\r\n\r\n") {
                let mut byte = [0];
                peer.read_exact(&mut byte).expect("read first head");
                received.push(byte[0]);
                assert!(received.len() <= 4096);
            }
        } else {
            received.resize(expected_first.len(), 0);
            peer.read_exact(&mut received).expect("read H2 prefix and frame header");
        }
        assert_eq!(received, expected_first);
        // The client sends the second slice only after these bytes crossed the proxy.
        peer.write_all(b"A").expect("acknowledge first write");
        let mut body = Vec::new();
        peer.read_to_end(&mut body).expect("read complete body and any unwanted tail");
        body
    });
    let mut config = ephemeral_proxy_config(&["--ip", "127.0.0.1"]);
    config.groups[0].actions.mod_http = ripdpi_packets::MH_DMIX | ripdpi_packets::MH_HOSTPAD;
    let proxy = start_proxy(config, None);
    let mut client: TcpStream = socks_connect(proxy.port, port);
    client.set_read_timeout(Some(Duration::from_secs(3))).expect("bound client read");
    client.write_all(first).expect("send first slice");
    let mut ack = [0];
    client.read_exact(&mut ack).expect("wait for actual origin receipt");
    assert_eq!(&ack, b"A");
    client.write_all(BODY).expect("send HTTP-looking body separately");
    client.shutdown(Shutdown::Write).expect("finish client request");
    let body = origin.join().expect("join origin");
    drop(client);
    drop(proxy);
    body
}
